const axios = require('axios');
await sendTrackedMessage(sock, remoteJid, '✨ Fetching inspiration...');
try {
  const res = await axios.get('https://zenquotes.io/api/random');
  if (res.data && res.data[0]) {
    await sendTrackedMessage(sock, remoteJid, `💬 "${res.data[0].q}"\n\n— ${res.data[0].a}`);
  } else {
    await sendTrackedMessage(sock, remoteJid, '❌ Could not fetch a quote.');
  }
} catch (e) {
  await sendTrackedMessage(sock, remoteJid, '❌ Quote service unavailable.');
}
